import itertools

items = {
    1: "삼다수 2L 6개입", 2: "제주 삼다수 2L 6병", 3: "삼다수 500ml 20개입",
    4: "신라면 120g 5개입", 5: "농심 신라면 5개", 6: "진라면 매운맛 5개입",
    7: "아이폰 16 투명 케이스", 8: "아이폰 16 케이스", 9: "갤럭시 S25 케이스",
}
STOP = {"케이스", "투명", "제주", "농심", "매운맛"}
blocks = {}
for i, s in items.items():
    first = [t for t in s.split() if t not in STOP][0]
    blocks.setdefault(first, []).append(i)
cand = [p for ids in blocks.values() for p in itertools.combinations(ids, 2)]
print("전체 쌍", len(list(itertools.combinations(items, 2))), "-> 후보 쌍", len(cand))
print(cand)
# 전체 쌍 36 -> 후보 쌍 5
# [(1, 2), (1, 3), (2, 3), (4, 5), (7, 8)]

import math

vec = {
    "삼다수 2L 6개입": (1.0, 0.10),
    "제주 삼다수 2L 6병": (0.98, 0.12),   # 정답 쌍
    "삼다수 500ml 20개입": (0.95, 0.20),  # 같은 브랜드·다른 규격
    "아이시스 2L 6개입": (0.85, 0.35),    # 다른 브랜드·같은 규격
    "신라면 5개입": (0.10, 0.99),
}
anchor, positive = "삼다수 2L 6개입", "제주 삼다수 2L 6병"

def cos(a, b):
    return (a[0]*b[0] + a[1]*b[1]) / (math.hypot(*a) * math.hypot(*b))

negs = sorted(((cos(vec[anchor], v), k) for k, v in vec.items()
               if k not in (anchor, positive)), reverse=True)
for s, k in negs:
    print(f"{s:.3f} {k}")
print("hard negative:", negs[0][1], "| easy negative:", negs[-1][1])
# 0.994 삼다수 500ml 20개입
# 0.958 아이시스 2L 6개입
# 0.199 신라면 5개입
# hard negative: 삼다수 500ml 20개입 | easy negative: 신라면 5개입
